using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Diagnostics;
using System.Reflection;
using System.Threading;
internal static class UpdateInstaller {
 internal static string Stage(string archive,string root,Version version){
  string folder=Path.Combine(root,"Updates",version.ToString(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string target=Path.Combine(folder,"MonEspace.exe");try{using(var zip=ZipFile.OpenRead(archive)){var entries=zip.Entries.Where(e=>e.FullName=="MonEspace.exe").ToList();if(entries.Count!=1||entries[0].Length<1024||entries[0].Length>100L*1024*1024)throw new InvalidDataException("L’archive ne contient pas une application Mon espace valide.");using(var input=entries[0].Open())using(var output=File.Create(target)){var buffer=new byte[81920];long total=0;int size;while((size=input.Read(buffer,0,buffer.Length))>0){total+=size;if(total>100L*1024*1024)throw new InvalidDataException("Application trop volumineuse.");output.Write(buffer,0,size);}}}var assembly=AssemblyName.GetAssemblyName(target);if(assembly.Name!="MonEspace"||assembly.Version!=version)throw new InvalidDataException("La version de l’application ne correspond pas au téléchargement annoncé.");return target;}catch{if(File.Exists(target))File.Delete(target);throw;}
 }
 internal static string Install(string staged,string root,Version version){string target=Path.Combine(root,"Versions",version.ToString(),"MonEspace.exe");Installation.Copy(staged,target);return target;}
 internal static void WaitForParent(int id){if(id<=0||id==Process.GetCurrentProcess().Id)throw new InvalidDataException("Processus de mise à jour invalide.");try{using(var parent=Process.GetProcessById(id))if(!parent.WaitForExit(60000))throw new IOException("Mon espace ne s’est pas fermé. Relancez la mise à jour depuis l’application.");}catch(ArgumentException){} }
 internal static void Test(string folder){string root=Path.Combine(folder,"update-installer");Directory.CreateDirectory(root);string archive=Path.Combine(root,"package.zip");if(File.Exists(archive))File.Delete(archive);using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create))zip.CreateEntryFromFile(Assembly.GetExecutingAssembly().Location,"MonEspace.exe");var version=Assembly.GetExecutingAssembly().GetName().Version;string staged=Stage(archive,root,version);Directory.CreateDirectory(Path.Combine(root,"Data"));File.WriteAllText(Path.Combine(root,"Data","state.json"),"preserved");string target=Install(staged,root,version);if(!File.Exists(target)||File.ReadAllText(Path.Combine(root,"Data","state.json"))!="preserved")throw new Exception("Installation mise à jour");bool fail=false;try{Stage(archive,root,new Version(9,9,9,9));}catch(InvalidDataException){fail=true;}if(!fail)throw new Exception("Version différente acceptée");File.Delete(archive);using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create)){using(var text=new StreamWriter(zip.CreateEntry("../MonEspace.exe").Open()))text.Write("unsafe");}fail=false;try{Stage(archive,root,version);}catch(InvalidDataException){fail=true;}if(!fail)throw new Exception("Archive avec chemin acceptée");File.WriteAllText(Path.Combine(folder,"UPDATE_INSTALLER_PASS.txt"),"PASS: real packaged executable, version match, isolated install, preserved data, invalid archive rejected. Real application relaunch requires interactive desktop verification.");}
}
internal sealed partial class ModernWorkspace {
 void InstallAvailableUpdate(){if(updateFound==null||owner.IsPreview)return;if(!FlushDeskNotes()||!ConfirmDocumentDrafts()||!owner.Save())return;if(IsAttachmentBusy){System.Windows.MessageBox.Show("Attendez la fin de la copie des fichiers.");return;}if(FocusClock.Active(store.Value.focus)){System.Windows.MessageBox.Show("Terminez ou annulez votre session de concentration avant de relancer l’application.");return;}var manifest=updateFound;UpdateOperation(async(client,token)=>{var version=new Version(manifest.version);string downloads=Path.Combine(Program.Root,"Updates");Directory.CreateDirectory(downloads);string archive=Path.Combine(downloads,"MonEspace-"+version+".zip");await client.Download(manifest,archive,token);token.ThrowIfCancellationRequested();string staged=UpdateInstaller.Stage(archive,Program.Root,version);token.ThrowIfCancellationRequested();string target=UpdateInstaller.Install(staged,Program.Root,version);if(IsAttachmentBusy||FocusClock.Active(store.Value.focus))throw new IOException("Une copie de fichiers ou une session de concentration est en cours. La version est prête ; réessayez après sa fin.");if(!FlushDeskNotes()||!ConfirmDocumentDrafts()||!owner.Save())throw new IOException("Les changements n’ont pas pu être enregistrés. La nouvelle version est prête ; réessayez.");if(!owner.BeginUpdate(target))throw new IOException("La fermeture a été annulée. Vos modifications restent ouvertes.");});}
}
internal sealed partial class MainForm {
 internal bool BeginUpdate(string target){
  // Start only after every FormClosing handler accepts the close.
  System.Windows.Forms.FormClosedEventHandler restart=delegate{try{Process.Start(new ProcessStartInfo(target,"--finish-update "+Process.GetCurrentProcess().Id){UseShellExecute=true});}catch(Exception ex){System.Windows.Forms.MessageBox.Show("La version est prête mais n’a pas pu démarrer : "+ex.Message+"\n\n"+target,"Mise à jour");}};
  FormClosed+=restart;RequestQuit();if(!IsDisposed){FormClosed-=restart;return false;}return true;
 }
}
internal static partial class Program {
 internal static bool FinishUpdate(string[] args){if(args.Length!=2||args[0]!="--finish-update")return false;int id;if(!Int32.TryParse(args[1],out id))throw new InvalidDataException("Processus de mise à jour invalide.");if(!Assembly.GetExecutingAssembly().Location.Equals(Installed,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("La mise à jour doit être lancée depuis sa version installée.");UpdateInstaller.WaitForParent(id);bool startup=Startup();Shortcut();if(startup)SetStartup(true);return true;}
}
